 pub proof fn lemma_kernel_alloc_one(pre: FrameAllocView, post: FrameAllocView, addr: int)
     requires
         pre.wf(),
     ensures
         pre.free_frames.contains(addr),
         post == pre.alloc_one(addr),
         post.wf(),
 {
     admit();
 }

